      );

      const input = getByTestId('brand-input-input');

      fireEvent.changeText(input, 'nike');

      act(() => {
        jest.advanceTimersByTime(150);
      });

      await waitFor(() => {
        expect(queryByTestId('brand-input-suggestions-list')).toBeTruthy();
      });

      // Blur
