    it('should mark suggestion buttons with proper role', async () => {
      mockGetBrandSuggestions.mockResolvedValue(['Nike']);

      const { getByTestId } = render(
        <BrandAutocompleteInput value="" onChange={jest.fn()} testID="brand-input" />
      );

